        base = {k: v for k, v in full.items() if k != "unit_price"}
        prices = {lvl: price_for(case, base, c, std) for lvl, c in c_levels.items()}
        out.append({"id": f"S{i}", "terms": base, "label": describe(case, full), "prices": prices})
