        bank = [c for c in claim_bank(case, self.facts, sid, self.rfq_offers(case, threads), sup_text)
                if not (set(c["ids"]) & self.used_claims)]
        transcript = []
        for m in ev:
            who = "BUYER (us)" if m.get("from") == "buyer" else f"SUPPLIER ({m.get('from')})"
            sheets = [s.get("terms") for s in m.get("term_sheets") or []]
            transcript.append({"from": who, "status": m.get("status"), "text": (m.get("body") or "")[:3000],
