uv run --locked python - <<'PY'
import json
from arena_kit.cli import load_env
from arena_kit.client import ArenaClient
load_env(); c=ArenaClient(); rows=c.sessions('practice'); rows=rows.get('sessions',rows) if isinstance(rows,dict) else rows
best={}
for r in rows:
 cid=r.get('case_id'); sc=r.get('score')
 if cid and cid.startswith('case:P') and isinstance(sc,(int,float)) and (cid not in best or sc>best[cid][0]): best[cid]=(sc,r['session_id'])
for cid,(score,sid) in sorted(best.items()):
 s=c.session(sid); trace=(s.get('result') or {}).get('trace') or []
 alts=[]
 for x in trace:
  m=x.get('move') or {}
  if x.get('actor')!='buyer' and m.get('alternatives'):
   alts.append((x.get('round'),m.get('status'),m.get('terms'),[(a.get('offer_id'),a.get('terms')) for a in m['alternatives']]))
 print('\n',cid,score,sid,'deal=',(s.get('result') or {}).get('terms'))
 for a in alts: print(' ALT',a)
PY

