ppi='The PPI-C2431 index fell 2.3 % between idx:PPI-C2431@2026-06 and idx:PPI-C2431@2026-08.'
steps=[
(5.20,["po:4500013967-10","po:4500014022-10","po:4500014078-10"],po,'Our documented order history supports a competitive fixed-price package.'),
(5.23,['fc:370010@2026-09'],fc,'The shared demand forecast now provides the exact annual demand profile you requested.'),
(5.25,['idx:AS-14404@2026-06','idx:AS-14404@2026-09'],asx,'The recent alloy index movement should be reflected in the base price.'),
