]
def sheet(p): return {'term_sheet_id':None,'terms':{'unit_price':p,'index_clause':None,'payment_days':90,'contract_months':24}}
def offer_summary(rep):
    return {'status':rep.get('status'),'sheets':rep.get('term_sheets'),'claim_results':rep.get('claim_results'),'result':rep.get('result')}
for i,(price,refs,claim,context) in enumerate(steps,1):
    body=(f'Dear Mr Seidl,\n\n{context} Our binding annual requirement is 23700 kg. '
