sheets=rep.get('term_sheets') or []
if not sheets: raise SystemExit('No standing sheet at endpoint')
ranked=sorted((total_cost(case,s['terms']),s) for s in sheets)
print('ENDPOINT_COSTS',[(round(cost,2),s['term_sheet_id'],s['terms']) for cost,s in ranked])
best=ranked[0][1]
if best is sheets[0] or best['term_sheet_id']==sheets[0]['term_sheet_id']:
    out=c.accept(sid,sheets[0]['term_sheet_id']); print('ACCEPT_PRIMARY',json.dumps(out,default=str)); raise SystemExit
