body='Dear Mr Seidl,\n\nWe can confirm the alternative package you have proposed on the terms below. Please confirm agreement.\n\nKind regards,\nHollerau Pumpenwerke GmbH, Purchasing'
rep2=c.send_message(sid,sup,{'subject':'Confirmation of revised package','body':body,'refs':[],'term_sheets':[{'term_sheet_id':None,'terms':terms}]})
print('MIRROR',json.dumps(offer_summary(rep2),default=str))
if rep2.get('result'): print('RESULT',json.dumps(rep2['result'],default=str))
elif rep2.get('term_sheets'): print('ACCEPT_MIRROR_REPLY',json.dumps(c.accept(sid,rep2['term_sheets'][0]['term_sheet_id']),default=str))
else: print('STATE',json.dumps(c.session(sid),default=str))
