uv run --locked python - <<'PY'
from collections import defaultdict, Counter
from concurrent.futures import ThreadPoolExecutor, as_completed
from arena_kit.cli import load_env
from arena_kit.client import ArenaClient
load_env(); c=ArenaClient(); rows=c.sessions('practice')
with ThreadPoolExecutor(max_workers=16) as ex:
 fut={ex.submit(c.session,x['session_id']):x for x in rows}
 states=[]
 for i,f in enumerate(as_completed(fut),1):
  try: states.append(f.result())
  except Exception as e: print('ERR',fut[f]['session_id'],e)
print('FETCHED',len(states))
by=defaultdict(list)
for s in states:
 r=s.get('result') or {}; by[s['case_id']].append((r.get('score') or 0,s['session_id'],r.get('terms'),s.get('rounds'),r.get('supplier_id')))
for case in sorted(by):
 print('\n###',case,'n',len(by[case]))
 for score,sid,terms,rounds,sup in sorted(by[case],reverse=True)[:15]: print(f'{score:.9f}',sid,'r'+str(rounds),sup,terms)
PY

