from concurrent.futures import ThreadPoolExecutor
from arena_kit.cli import load_env
from arena_kit.client import ArenaClient
load_env(); c=ArenaClient(); xs=[x for x in c.sessions('practice') if x['case_id']=='case:P02']
with ThreadPoolExecutor(max_workers=12) as ex: ss=list(ex.map(lambda x:c.session(x['session_id']),xs))
for s in ss:
 r=s.get('result') or {}; seq=[]
 for t in r.get('trace',[]):
  m=t.get('move') or {}; a=t.get('actor')
  if a=='buyer':
   if m.get('type')=='message':
    sh=[z.get('terms') for z in m.get('term_sheets') or []]; cl=[z.get('type') for z in (m.get('interpreted') or {}).get('claims',[])]
    seq.append('B'+str(t.get('round'))+':'+str(sh)+':'+str(cl))
   elif m.get('type') in ('accept','walk_away'): seq.append('B:'+m.get('type')+':'+str(m.get('offer_id')))
  elif a and a.startswith('sup:'):
   seq.append('S'+str(t.get('round'))+':'+str(m.get('status'))+':'+str(m.get('terms')))
 print('\n',s['session_id'],'score',round(r.get('score') or 0,6),'rounds',s.get('rounds'))
 print('\n'.join(seq))
