print('n',n,'last',since,'kinds',sorted(kinds))
for e in found:
 print(json.dumps(e,ensure_ascii=False))
PY","workdir":"/Users/sametdegirmenci/Downloads/ysamet-breakthrough/tacto-negotiator","yield_time_ms":30000,"max_output_tokens":30000}); text(JSON.stringify(r));

