def sheet(price, clause):
    return {'term_sheet_id': None, 'terms': {
        'unit_price': price, 'payment_days': 90,
        'index_clause': clause, 'contract_months': 24}}

def send(body, refs, ts):
    out = c.send_message(sid, 'sup:70740', {
        'subject': subject, 'body': body, 'refs': refs,
        'term_sheets': [ts]})
    th = c.thread(sid, 'sup:70740')
    print(json.dumps({'send_response': out, 'thread': th}, ensure_ascii=False), flush=True)
    return th

def latest_supplier(th):
    # The thread endpoint may be either the thread object itself or a trace wrapper.
    if isinstance(th, dict) and isinstance(th.get('offer_id'), str):
        return th
    moves = th.get('moves') or th.get('trace') or []
    for item in reversed(moves):
        move = item.get('move', item) if isinstance(item, dict) else {}
        if isinstance(move, dict) and isinstance(move.get('offer_id'), str):
            return move
    return {}

